"use client";

import { type ComponentPropsWithoutRef, type ReactNode, type ForwardedRef, forwardRef } from "react";
import { useList, type ListContextValue, type Key, ItemContext, useItem } from "./sortable-list-state";
import { Reorder, useDragControls } from "motion/react";
import { cn } from "@/lib/utils";

export type SortableListContentProps = Omit<ComponentPropsWithoutRef<"ul">, "children" | "onDrag" | "onDragStart" | "onDragEnd" | "onAnimationStart"> & {
  /** Renders each item; wrap the result in SortableListItem. */
  children: (item: never, index: number) => ReactNode;
};

export function SortableListContentInner<T>(
  { className, children, ...props }: Omit<SortableListContentProps, "children"> & { children: (item: T, index: number) => ReactNode },
  ref: ForwardedRef<HTMLUListElement>,
) {
  const { ids, byId, setLocal, draggingId, status } = useList("SortableListContent") as ListContextValue<T>;
  if (ids.length === 0) return null;
  return (
    <Reorder.Group
      ref={ref}
      as="ul"
      axis="y"
      values={ids}
      // Every drag step only previews; the drop decides whether the order changes.
      onReorder={(next) => draggingId !== null && setLocal(next)}
      aria-busy={status === "pending" || undefined}
      className={cn("flex flex-col gap-2", className)}
      // DOM drag handlers are omitted from the props type, so the rest are safe to pass to Motion.
      {...(props as object)}
    >
      {ids.map((id, index) => (
        <ItemSlot key={id} id={id} index={index}>
          {children(byId.get(id) as T, index)}
        </ItemSlot>
      ))}
    </Reorder.Group>
  );
}

/** The ordered list. Pass a render function that returns a SortableListItem. */
export const SortableListContent = forwardRef(SortableListContentInner) as <T>(
  props: Omit<SortableListContentProps, "children"> & { children: (item: T, index: number) => ReactNode; ref?: ForwardedRef<HTMLUListElement> },
) => ReturnType<typeof SortableListContentInner>;

export function ItemSlot({ id, index, children }: { id: Key; index: number; children: ReactNode }) {
  const { byId, locked, disabled, status } = useList("SortableListItem");
  const controls = useDragControls();
  const item = byId.get(id);
  const movable = item !== undefined && !disabled && status !== "pending" && !locked(item);
  return <ItemContext.Provider value={{ id, index, controls, movable }}>{children}</ItemContext.Provider>;
}

export type SortableListItemProps = Omit<ComponentPropsWithoutRef<"li">, "onDrag" | "onDragStart" | "onDragEnd" | "onAnimationStart">;

/** One row. Dragging starts only from its SortableListHandle, so the rest of the row stays clickable and scrollable. */
export const SortableListItem = forwardRef<HTMLLIElement, SortableListItemProps>(function SortableListItem({ className, ...props }, ref) {
  const { animated, draggingId, endDrag, locked, byId } = useList("SortableListItem");
  const { id, controls } = useItem("SortableListItem");
  const item = byId.get(id);
  return (
    <Reorder.Item
      ref={ref}
      value={id}
      dragListener={false}
      dragControls={controls}
      // Motion's own Space-to-grab keyboard mode is replaced by the move buttons and handle arrows.
      tabIndex={-1}
      transition={animated ? undefined : { duration: 0 }}
      onDragEnd={() => endDrag(id)}
      data-dragging={draggingId === id ? "" : undefined}
      data-locked={item !== undefined && locked(item) ? "" : undefined}
      className={cn(
        "relative flex items-center gap-2 rounded-md border border-border bg-background p-2 text-sm outline-none transition-shadow data-[dragging]:shadow-lg data-[dragging]:ring-2 data-[dragging]:ring-ring/20",
        className,
      )}
      {...(props as object)}
    />
  );
});

"use client";

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { useList, useItem, type SortableListFailure, type ListContextValue } from "./sortable-list-state";
import { cn } from "@/lib/utils";

export const iconButton =
  "inline-flex size-8 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:bg-accent focus-visible:text-accent-foreground aria-disabled:pointer-events-none aria-disabled:opacity-40 [&_svg]:size-4";

/**
 * Drag handle. Press and drag to reorder; Up and Down arrows also move the row.
 * Unavailable moves use aria-disabled so focus stays put when a row reaches an end.
 */
export const SortableListHandle = forwardRef<HTMLButtonElement, ComponentPropsWithoutRef<"button">>(function SortableListHandle(
  { className, children, onPointerDown, onKeyDown, ...props },
  ref,
) {
  const { label, messages, byId, startDrag, move, canMoveTo, ids } = useList("SortableListHandle");
  const { id, index, controls, movable } = useItem("SortableListHandle");
  // Positions this row can reach. None (for example the only item) makes the handle unavailable.
  const reachable = ids.map((_, position) => position).filter((position) => canMoveTo(id, position));
  const available = movable && reachable.length > 0;
  return (
    <button
      ref={ref}
      type="button"
      aria-label={messages.handle(label(byId.get(id)))}
      aria-disabled={!available || undefined}
      aria-roledescription="drag handle"
      className={cn(iconButton, "cursor-grab touch-none active:cursor-grabbing", className)}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (!available || event.defaultPrevented || event.button !== 0) return;
        startDrag(id);
        controls.start(event);
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (!available || event.defaultPrevented) return;
        // Home and End go to the furthest position the row can reach, skipping locked slots at the ends.
        const to =
          event.key === "ArrowUp" ? index - 1 : event.key === "ArrowDown" ? index + 1 : event.key === "Home" ? reachable[0] : event.key === "End" ? reachable.at(-1) : undefined;
        if (to === undefined || !["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return;
        event.preventDefault();
        if (canMoveTo(id, to)) move(id, to);
      }}
      {...props}
    >
      {children ?? (
        <svg aria-hidden viewBox="0 0 16 16" fill="currentColor">
          {[4, 8, 12].flatMap((y) => [6, 10].map((x) => <circle key={`${x}-${y}`} cx={x} cy={y} r="1.25" />))}
        </svg>
      )}
    </button>
  );
});

export const MoveButton = forwardRef<HTMLButtonElement, ComponentPropsWithoutRef<"button"> & { direction: -1 | 1 }>(function MoveButton(
  { direction, className, children, onClick, ...props },
  ref,
) {
  const { label, messages, byId, move, canMoveTo } = useList(direction < 0 ? "SortableListMoveUp" : "SortableListMoveDown");
  const { id, index } = useItem(direction < 0 ? "SortableListMoveUp" : "SortableListMoveDown");
  const target = index + direction;
  const available = canMoveTo(id, target);
  return (
    <button
      ref={ref}
      type="button"
      aria-label={(direction < 0 ? messages.moveUp : messages.moveDown)(label(byId.get(id)))}
      aria-disabled={!available || undefined}
      className={cn(iconButton, className)}
      onClick={(event) => {
        onClick?.(event);
        if (available && !event.defaultPrevented) move(id, target);
      }}
      {...props}
    >
      {children ?? (
        <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round">
          <path d={direction < 0 ? "M4 10l4-4 4 4" : "M4 6l4 4 4-4"} />
        </svg>
      )}
    </button>
  );
});

export const SortableListMoveUp = forwardRef<HTMLButtonElement, ComponentPropsWithoutRef<"button">>(function SortableListMoveUp(props, ref) {
  return <MoveButton ref={ref} direction={-1} {...props} />;
});

export const SortableListMoveDown = forwardRef<HTMLButtonElement, ComponentPropsWithoutRef<"button">>(function SortableListMoveDown(props, ref) {
  return <MoveButton ref={ref} direction={1} {...props} />;
});

/** Shown only when there are no items. */
export const SortableListEmpty = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function SortableListEmpty({ className, ...props }, ref) {
  const { ids } = useList("SortableListEmpty");
  if (ids.length > 0) return null;
  return <div ref={ref} className={cn("rounded-md border border-dashed border-border p-6 text-center text-sm text-muted-foreground", className)} {...props} />;
});

export type SortableListErrorProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  children?: ReactNode | ((failure: SortableListFailure<unknown>) => ReactNode);
  retryLabel?: string;
};

/**
 * Shown after the app rejects a move. The order is already restored; Retry saves the move again.
 * A red tint mixed with the background, so it stays opaque over any surface.
 */
export const SortableListError = forwardRef<HTMLDivElement, SortableListErrorProps>(function SortableListError(
  { className, children, retryLabel = "Retry", ...props },
  ref,
) {
  const { failure, retry, canRetry } = useList("SortableListError");
  if (!failure) return null;
  return (
    <div ref={ref} role="alert" className={cn("flex items-center justify-between gap-3 rounded-md border border-[color-mix(in_oklab,var(--destructive)_30%,var(--background))] bg-[color-mix(in_oklab,var(--destructive)_12%,var(--background))] px-3 py-2 text-sm text-destructive", className)} {...props}>
      <span>{typeof children === "function" ? children(failure) : (children ?? "Couldn't save the new order.")}</span>
      <button type="button" aria-disabled={!canRetry || undefined} onClick={retry} className="shrink-0 rounded-sm font-medium underline underline-offset-4 focus-visible:outline-none focus-visible:decoration-2 aria-disabled:opacity-50">
        {retryLabel}
      </button>
    </div>
  );
});

/** State and actions of the nearest SortableList, for building your own parts. */
export function useSortableList<T = unknown>() {
  const { ids, byId, status, failure, move, retry, dismiss } = useList("useSortableList") as ListContextValue<T>;
  return { items: ids.map((id) => byId.get(id) as T), status, failure, move, retry, dismiss };
}

"use client";

import { moveKey, type Key } from "./sortable-list-state";

type FailedMove = { order: Key[]; from: number; to: number };

/** Reapply only the failed item's placement to current rows, retaining all other host changes. */
export function planRetry(failure: FailedMove, id: Key, current: Key[]) {
  const from = current.indexOf(id);
  if (from < 0) return null;
  const savedPosition = failure.order.indexOf(id);
  if (savedPosition < 0) return null;
  const present = new Set(current);
  const before = failure.order.slice(0, savedPosition).reverse().find(key => present.has(key));
  const after = failure.order.slice(savedPosition + 1).find(key => present.has(key));
  const down = failure.to > failure.from;
  const anchor = down ? before ?? after : after ?? before;
  if (anchor === undefined) return null;
  const insertAfter = down ? before !== undefined : after === undefined;
  // Compute the insertion slot after taking the moved row out of the current order.
  let to = current.indexOf(anchor) + (insertAfter ? 1 : 0);
  if (from < to) to--;
  if (from === to) return null;
  return { id, from, to, order: moveKey(current, from, to) };
}

"use client";

import { type SortableListProps, type Key, type SortableListStatus, type SortableListFailure, defaultMessages, type ListContextValue, moveKey, ListContext } from "./sortable-list-state";
import { type ForwardedRef, useState, useRef, useEffect, forwardRef } from "react";
import { useReducedMotion } from "motion/react";
import { planRetry } from "./sortable-list-retry";
import { cn } from "@/lib/utils";

export function SortableListRoot<T>(
  { items, getId, getLabel = () => "Item", onOrderChange, isLocked = () => false, disabled = false, motion = true, messages: messageOverrides, className, children, ...props }: SortableListProps<T>,
  ref: ForwardedRef<HTMLDivElement>,
) {
  // A drag preview or a save in flight; otherwise the app's order shows.
  const [local, setLocal] = useState<Key[] | null>(null);
  const [status, setStatus] = useState<SortableListStatus>("idle");
  const [failure, setFailure] = useState<SortableListFailure<T> | null>(null);
  const [draggingId, setDraggingId] = useState<Key | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const dragFrom = useRef(-1);
  const cancelled = useRef(false);
  const attempt = useRef(0);
  const reduced = useReducedMotion();
  const messages = { ...defaultMessages, ...messageOverrides };

  const byId = new Map(items.map((item) => [getId(item), item] as const));
  const appIds = items.map(getId);
  // Keep the preview's order but follow the app's items: drop removed ones, append new ones.
  const ids = local ? [...local.filter((id) => byId.has(id)), ...appIds.filter((id) => !local.includes(id))] : appIds;

  // Re-reading the same sentence must still be announced; alternate a zero-width space.
  const announce = (text: string) => setAnnouncement((previous) => (previous === text ? `${text}​` : text));

  const commit = (order: Key[], id: Key, from: number, to: number) => {
    const item = byId.get(id) as T;
    const name = getLabel(item);
    const move = { item, from, to };
    const token = ++attempt.current;
    setFailure(null);
    announce(messages.moved(name, to + 1, order.length));
    const result = onOrderChange?.(order.flatMap((key) => (byId.has(key) ? [byId.get(key) as T] : [])), move);
    if (!(result instanceof Promise)) {
      setLocal(null);
      setStatus("idle");
      return;
    }
    setLocal(order);
    setStatus("pending");
    result.then(
      () => {
        if (token !== attempt.current) return;
        setLocal(null);
        setStatus("idle");
      },
      (cause: unknown) => {
        if (token !== attempt.current) return;
        setLocal(null);
        setStatus("error");
        setFailure({ ...move, order, cause });
        announce(messages.restored(name, from + 1));
      },
    );
  };

  // Locked items keep their positions in the app's order, so no move may shift one.
  const keepsLocked = (order: Key[]) =>
    appIds.every((key, index) => {
      const item = byId.get(key);
      return item === undefined || !isLocked(item) || order[index] === key;
    });

  const canMove = (id: Key) => {
    const item = byId.get(id);
    return item !== undefined && !disabled && status !== "pending" && !isLocked(item);
  };

  const retryPlan = failure ? planRetry(failure, getId(failure.item), appIds) : null;
  const canRetry = retryPlan !== null && canMove(retryPlan.id) && keepsLocked(retryPlan.order);

  const value: ListContextValue<T> = {
    ids,
    byId,
    label: getLabel,
    messages,
    locked: isLocked,
    disabled,
    animated: motion && !reduced,
    status,
    failure,
    draggingId,
    setLocal,
    startDrag: (id) => {
      dragFrom.current = ids.indexOf(id);
      cancelled.current = false;
      setDraggingId(id);
    },
    endDrag: (id) => {
      setDraggingId(null);
      const to = ids.indexOf(id);
      if (cancelled.current || to === dragFrom.current || to < 0 || !keepsLocked(ids)) return setLocal(null);
      commit(ids, id, dragFrom.current, to);
    },
    move: (id, to) => {
      if (value.canMoveTo(id, to)) commit(moveKey(ids, ids.indexOf(id), to), id, ids.indexOf(id), to);
    },
    canMoveTo: (id, to) => {
      const from = ids.indexOf(id);
      return canMove(id) && from >= 0 && to >= 0 && to < ids.length && to !== from && keepsLocked(moveKey(ids, from, to));
    },
    canRetry,
    retry: () => {
      if (canRetry && retryPlan) commit(retryPlan.order, retryPlan.id, retryPlan.from, retryPlan.to);
    },
    dismiss: () => {
      setFailure(null);
      setStatus("idle");
    },
  };

  // Escape cancels a pointer drag and restores the order it started from.
  useEffect(() => {
    if (draggingId === null) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      cancelled.current = true;
      setLocal(null);
      setDraggingId(null);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [draggingId]);

  return (
    <ListContext.Provider value={value as ListContextValue<unknown>}>
      <div ref={ref} data-status={status} data-disabled={disabled ? "" : undefined} className={cn("flex flex-col gap-3", className)} {...props}>
        {children}
        <div role="status" aria-live="polite" className="sr-only">
          {announcement}
        </div>
      </div>
    </ListContext.Provider>
  );
}

export const SortableList = forwardRef(SortableListRoot) as <T>(
  props: SortableListProps<T> & { ref?: ForwardedRef<HTMLDivElement> },
) => ReturnType<typeof SortableListRoot>;

"use client";

import { createContext, useContext, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { type DragControls } from "motion/react";

export type Key = string | number;

/** The move the list asked the app to save. Positions are zero-based. */
export type SortableListMove<T> = { item: T; from: number; to: number };

/** A move the app rejected. `cause` is whatever onOrderChange threw. */
export type SortableListFailure<T> = SortableListMove<T> & { order: Key[]; cause: unknown };

export type SortableListStatus = "idle" | "pending" | "error";

/** Button labels and screen reader announcements. Positions are one-based. Replace any of them, for example to translate. */
export type SortableListMessages = {
  handle: (label: string) => string;
  moveUp: (label: string) => string;
  moveDown: (label: string) => string;
  moved: (label: string, position: number, total: number) => string;
  restored: (label: string, position: number) => string;
};

export const defaultMessages: SortableListMessages = {
  handle: (label) => `Reorder ${label}`,
  moveUp: (label) => `Move ${label} up`,
  moveDown: (label) => `Move ${label} down`,
  moved: (label, position, total) => `${label} moved to position ${position} of ${total}.`,
  restored: (label, position) => `Couldn't save. ${label} is back at position ${position}.`,
};

export type ListContextValue<T> = {
  ids: Key[];
  byId: Map<Key, T>;
  label: (item: T) => string;
  messages: SortableListMessages;
  locked: (item: T) => boolean;
  disabled: boolean;
  animated: boolean;
  status: SortableListStatus;
  failure: SortableListFailure<T> | null;
  draggingId: Key | null;
  setLocal: (ids: Key[] | null) => void;
  startDrag: (id: Key) => void;
  endDrag: (id: Key) => void;
  move: (id: Key, to: number) => void;
  /** Whether moving this item to `to` is allowed right now. */
  canMoveTo: (id: Key, to: number) => boolean;
  canRetry: boolean;
  retry: () => void;
  dismiss: () => void;
};

export const ListContext = createContext<ListContextValue<unknown> | null>(null);

export type ItemContextValue = { id: Key; index: number; controls: DragControls; movable: boolean };

export const ItemContext = createContext<ItemContextValue | null>(null);

export function useList(part: string) {
  const context = useContext(ListContext);
  if (!context) throw new Error(`<${part}> must be used inside <SortableList>.`);
  return context;
}

export function useItem(part: string) {
  const context = useContext(ItemContext);
  if (!context) throw new Error(`<${part}> must be used inside <SortableListItem>.`);
  return context;
}

export const moveKey = (ids: Key[], from: number, to: number) => {
  const next = [...ids];
  next.splice(to, 0, ...next.splice(from, 1));
  return next;
};

export type SortableListProps<T> = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** The app's ordered items. The list never reorders them itself. */
  items: T[];
  /** A stable identity for each item. Never derived from position. */
  getId: (item: T) => Key;
  /** Name used in button labels and announcements, such as a task title. */
  getLabel?: (item: T) => string;
  /**
   * Called once per completed move with the new order. Save it and update `items`.
   * Return a promise to show pending; rejecting restores your order and offers retry.
   */
  onOrderChange?: (items: T[], move: SortableListMove<T>) => void | Promise<unknown>;
  /** Items that stay where they are. */
  isLocked?: (item: T) => boolean;
  disabled?: boolean;
  /** Layout and lift animation. Reduced motion is always honored. */
  motion?: boolean;
  /** Replace button labels and announcements, for example to translate them. */
  messages?: Partial<SortableListMessages>;
  children?: ReactNode;
};

"use client";

export { type SortableListMove, type SortableListFailure, type SortableListStatus, type SortableListMessages, type SortableListProps } from "./sortable-list-state";
export { SortableList } from "./sortable-list-root";
export { type SortableListContentProps, SortableListContent, type SortableListItemProps, SortableListItem } from "./sortable-list-content";
export { SortableListHandle, SortableListMoveUp, SortableListMoveDown, SortableListEmpty, type SortableListErrorProps, SortableListError, useSortableList } from "./sortable-list-controls";
